import type { Metadata } from 'next';
import { routeByPath, SITE_URL } from '@/lib/routes';

const ROUTE = '/services/publication-support/journal-submission/';
const meta = routeByPath.get(ROUTE)!;

export const metadata: Metadata = {
  title: meta.title,
  description: meta.description,
  alternates: { canonical: SITE_URL + ROUTE },
  openGraph: {
    title: meta.title,
    description: meta.description,
    url: SITE_URL + ROUTE,
    type: 'website',
    images: ["https://pubrica.com/share/pubrica-card.jpg"],
  },
};

const schema = [{"@context":"https://schema.org","@type":"Service","name":"Journal Submission Service","serviceType":"Journal submission, cover letter and editorial tracking","provider":{"@type":"Organization","name":"Pubrica","url":"https://pubrica.com/"},"url":"https://pubrica.com/services/publication-support/journal-submission/","description":"Portal submission through Editorial Manager, ScholarOne and eJournalPress, with a cover letter written for the editor and the status tracked.","areaServed":"Worldwide","audience":{"@type":"Audience","audienceType":"Researchers, PhD scholars, research institutions, medical writers and life-science teams"}},{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"How do I submit a manuscript to a journal, and what does a submission service do?","acceptedAnswer":{"@type":"Answer","text":"It takes the manuscript you have finished and carries it through the journal’s online submission system correctly: the account, the file set in the formats the portal demands, roughly forty metadata fields, co-author records and ORCIDs, every declaration, the reporting checklist and the cover letter. After that it watches the submission process, answers editorial-office queries and keeps you to the deadlines the journal sets. The science stays yours; the administration stops being yours."}},{"@type":"Question","name":"Who submits — you or me?","acceptedAnswer":{"@type":"Answer","text":"Either, and we ask before we start. Most authors give us portal access and we submit on their behalf once they have approved the cover letter and the built PDF. Where you would rather keep the login, we prepare every file and every field, send you a checklist in portal order, and stay on a call while you click through it. The corresponding author is always a named author, never us."}},{"@type":"Question","name":"Do you write the cover letter?","acceptedAnswer":{"@type":"Answer","text":"Yes, free with every submission. It is written for that editor and that journal — what the study found with the effect size, why the scope fits with two of the journal's own recent papers cited, what is new, and the declarations editors screen for. It runs to one page, because the first paragraph and the declarations are the parts that get read. Nothing is sent until you have approved it."}},{"@type":"Question","name":"How do you choose suggested reviewers?","acceptedAnswer":{"@type":"Answer","text":"From researchers actively publishing on your outcome measure or your method, then screened: no shared institution, no co-authorship within the journal's stated window, no common funder, no supervisory relationship. A name that fails any of those is dropped before submission rather than declared afterwards. Where a journal permits opposed reviewers we supply them only when there is a genuine competing group and a reason worth writing down."}},{"@type":"Question","name":"How long does submission take, and how long until a decision?","acceptedAnswer":{"@type":"Answer","text":"Submission itself takes two to three working days from your approval. The decision is the journal's to make and the honest range is wide: two to fourteen days at desk screening, one to eight weeks to secure reviewers, then three to ten weeks for reports. Anyone quoting you a firm date for a first decision is quoting a hope. What we can promise is that the wait is not being extended by anything on our side."}},{"@type":"Question","name":"Why do manuscripts get desk-rejected before review?","acceptedAnswer":{"@type":"Answer","text":"Roughly half of all rejections happen here, and they split into two kinds. Scientific: out of scope, too narrow, not novel enough for that title — which is a journal-selection problem. Administrative: a missing declaration, an unsigned conflict form, a figure below resolution, an incomplete checklist, an author record that was never confirmed. The second kind costs you a full cycle and contains no information about your work at all."}},{"@type":"Question","name":"Which submission portals do you work in?","acceptedAnswer":{"@type":"Answer","text":"Editorial Manager, ScholarOne, eJournalPress, Snapp and Open Journal Systems, which between them cover Elsevier, Springer Nature, Wiley, Taylor & Francis, SAGE, BMJ, PLOS, MDPI and most society and independent titles. Each asks for the same information in a different order with different file rules, and several society journals only accept submissions during an open window — worth knowing before the deadline, not after."}},{"@type":"Question","name":"What happens if my paper is rejected?","acceptedAnswer":{"@type":"Answer","text":"We send you the decision with the reports the same day and a plain summary of what each reviewer is asking for, then advise on whether to revise, appeal or move on. If you move on, resubmission to the next journal is included from the Gold pack: reformatted to the new template, a new cover letter, the whole portal again. Rejection is the normal case rather than the exception, and the useful response is a fast one."}},{"@type":"Question","name":"Can you submit the same manuscript to several journals at once?","acceptedAnswer":{"@type":"Answer","text":"No. Simultaneous submission breaches the declaration you sign at upload and is grounds for retraction at every journal involved, with the damage attaching to your name. What we do instead is have the next target chosen and the reformatting ready, so that a rejection turns into a new submission in days rather than weeks. Preprint servers are a separate matter and most journals permit them — we check that title by title."}},{"@type":"Question","name":"Do you handle proofs, licences and article processing charges?","acceptedAnswer":{"@type":"Answer","text":"In the Platinum pack, yes. Acceptance brings a copyright transfer or open-access licence to choose, an APC where the journal levies one, and galley proofs with a window that is often only forty-eight hours. We check proofs line by line against the accepted manuscript, because typesetting introduces errors that were not in your file, collate corrections from all co-authors into one return, flag any waiver you may be eligible for, and confirm the DOI once it is live."}}]},{"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://pubrica.com/"},{"@type":"ListItem","position":2,"name":"Publication support","item":"https://pubrica.com/services/publication-support/"},{"@type":"ListItem","position":3,"name":"Journal submission","item":"https://pubrica.com/services/publication-support/journal-submission/"}]}];

